Status DFSIterativeStrong(Graph G, int start) {
    int n = VexCount(G);
    if (n == 0 || start < 0 || start >= n) return ERROR;
    bool visited[MAXV] = {false};
    Stack S; InitStack(&S);

    visited[start] = true; Visit(start);
    Push(&S, (Frame){start, FirstAdjVex(G, start)});
    while (!StackEmpty(S)) {
        Frame f; GetTop(S, &f);
        if (f.next == NONE) { Pop(&S, &f); continue; }

        int w = f.next;
        f.next = NextAdjVex(G, f.v, w);
        ReplaceTop(&S, f);
        if (!visited[w]) {
            visited[w] = true; Visit(w);
            Push(&S, (Frame){w, FirstAdjVex(G, w)});
        }
    }
    return OK;
}
```

强连通且非空保证从任一 `start` 都会访问全部顶点；若用于一般图，需要在栈清空后从未访问顶点重新启动。若 ADT 的邻点迭代器对每条弧总共前进一次，时间 O(n+m)，栈和标记空间 O(n)；具体存储结构若让 `NextAdjVex` 线性搜索，复杂度应相应增加。

